.Synopsis; Force Install Updates on Remote Computer; .DESCRIPTION; Force Install Updates on Remote Computer using a scheduled task; .EXAMPLE; InstallUpdates -Computer "server1.contoso.com" -User "Contoso\Administrator" -Password "Password"; .NOTES; Version 1.0 - Initial Script; Written by Darryl van der Peijl; Date: 30.05.2014; Use at own risk; Function InstallUpdates {; param($Computer,$User,$Password); $SecurePassword = ConvertTo-SecureString  String $Password  AsPlainText -Force; $Credential = New-Object  TypeName System.Management.Automation.PSCredential  ArgumentList $User, $SecurePassword; Invoke-Command -ComputerName $Computer -credential $Credential -ScriptBlock {; $DateAndTime = (Get-Date -format ddMMMyyyy-HH.mm); Register-ScheduledJob -Name "InstallUpdates $DateAndTime" -RunNow -ScriptBlock {; $Criteria = "IsInstalled=0 and Type='Software'";`; $Searcher = New-Object -ComObject Microsoft.Update.Searcher;`; $SearchResult = $Searcher.Search($Criteria).Updates;`; $Session = New-Object -ComObject Microsoft.Update.Session;`; $Downloader = $Session.CreateUpdateDownloader();`; $Downloader.Updates = $SearchResult;`; $Downloader.Download();`; $Installer = New-Object -ComObject Microsoft.Update.Installer;`; $Installer.Updates = $SearchResult;`; $Result = $Installer.Install();`; }; }; }